package spec

import (
	"bytes"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// JavaHeader is the first line of the generated RulesGen.java.
const JavaHeader = "// Code generated by fldlint; DO NOT EDIT."

// javaPackage is the package of the generated file; the hand-written Rule,
// Binding and SkipCategory classes live in the same package.
const javaPackage = "io.github.jh125486.fldlint.spec"

// templateArg matches one template placeholder: {{name}} (JS and Go) or
// #{name} / #{name:type} / #{any(T)} (Java, OpenRewrite).
var templateArg = regexp.MustCompile(`\{\{([^}]*)\}\}|#\{([^}]*)\}`)

// TemplateArgs lists the placeholders of a template in order of appearance
// (ADR 009 D4: OpenRewrite binds arguments by that order, not by name). A
// typed Java placeholder yields its name (`key:any(String)` gives "key"); an
// anonymous one yields its whole body (`any(dev.openfeature.sdk.Client)`).
func TemplateArgs(template string) []string {
	var out []string
	for _, m := range templateArg.FindAllStringSubmatch(template, -1) {
		name := m[1]
		if strings.HasPrefix(m[0], "#{") {
			name = m[2]
			if !strings.HasPrefix(name, "any(") {
				name, _, _ = strings.Cut(name, ":")
			}
		}
		out = append(out, name)
	}
	return out
}

// GenerateJava renders RulesGen.java content for rf, deterministically.
// Every language binding is emitted (sorted by language name), unlike the Go
// table, because the Java engine also needs the JS and Go method names for
// reporting.
func GenerateJava(rf *RulesFile) []byte {
	var b bytes.Buffer
	b.WriteString(JavaHeader + "\n\n")
	fmt.Fprintf(&b, "package %s;\n\n", javaPackage)
	b.WriteString("import java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.Collections;\n")
	b.WriteString("import java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n")
	b.WriteString("/** The rules table generated from spec/generated/spec.json. */\n")
	b.WriteString("public final class RulesGen {\n")
	b.WriteString("    private RulesGen() {\n    }\n\n")

	b.WriteString("    /** Skip categories by name, sorted by name. */\n")
	b.WriteString("    public static final Map<String, SkipCategory> SKIP_CATEGORIES;\n\n")
	b.WriteString("    /** Every rule, in rules.yaml order. */\n")
	b.WriteString("    public static final List<Rule> RULES;\n\n")
	b.WriteString("    static {\n")
	b.WriteString("        Map<String, SkipCategory> categories = new LinkedHashMap<String, SkipCategory>();\n")
	for _, k := range rf.SkipCategoryNames() {
		c := rf.SkipCategories[k]
		fmt.Fprintf(&b, "        categories.put(%s, new SkipCategory(%s, %s));\n", jstr(k), jstr(c.Severity), jstr(c.Message))
	}
	b.WriteString("        SKIP_CATEGORIES = Collections.unmodifiableMap(categories);\n\n")
	b.WriteString("        List<Rule> rules = new ArrayList<Rule>();\n")
	for _, r := range rf.Rules {
		fmt.Fprintf(&b, "        rules.add(new Rule(%s, %s, %s,\n", jstr(r.ID), jstr(r.ValueType), jstr(r.Risk))
		fmt.Fprintf(&b, "                %d, %d, %d,\n", r.KeyArg, r.DefaultArg, r.ContextArg)
		fmt.Fprintf(&b, "                %s, %s,\n", jstr(r.Skip), jstr(r.Message))
		langs := make([]string, 0, len(r.Langs))
		for l := range r.Langs {
			langs = append(langs, l)
		}
		sort.Strings(langs)
		b.WriteString("                bindings(")
		for i, l := range langs {
			if i > 0 {
				b.WriteString(",")
			}
			bd := r.Langs[l]
			fmt.Fprintf(&b, "\n                        %s, new Binding(%s,\n", jstr(l), jlist(bd.Methods))
			fmt.Fprintf(&b, "                                %s,\n", jctx(bd.CtxArg))
			fmt.Fprintf(&b, "                                %s, %s,\n", jstr(bd.Template), jlist(TemplateArgs(bd.Template)))
			fmt.Fprintf(&b, "                                %s, %t)", jlist(bd.Requires), bd.Async)
		}
		b.WriteString(")));\n")
	}
	b.WriteString("        RULES = Collections.unmodifiableList(rules);\n")
	b.WriteString("    }\n\n")

	b.WriteString("    /** Finds the rule bound to a LaunchDarkly Java method name, or null. */\n")
	b.WriteString("    public static Rule lookupJavaMethod(String method) {\n")
	b.WriteString("        for (Rule rule : RULES) {\n")
	b.WriteString("            Binding binding = rule.getLanguages().get(\"java\");\n")
	b.WriteString("            if (binding != null && binding.getMethods().contains(method)) {\n")
	b.WriteString("                return rule;\n            }\n        }\n        return null;\n    }\n\n")

	b.WriteString("    private static List<String> list(String... values) {\n")
	b.WriteString("        return Collections.unmodifiableList(Arrays.asList(values));\n    }\n\n")
	b.WriteString("    /** Alternating keys and values: language, Binding, language, Binding, ... */\n")
	b.WriteString("    private static Map<String, Binding> bindings(Object... kv) {\n")
	b.WriteString("        Map<String, Binding> out = new LinkedHashMap<String, Binding>();\n")
	b.WriteString("        for (int i = 0; i < kv.length; i += 2) {\n")
	b.WriteString("            out.put((String) kv[i], (Binding) kv[i + 1]);\n        }\n")
	b.WriteString("        return Collections.unmodifiableMap(out);\n    }\n\n")
	b.WriteString("    /** Alternating keys and values: method, argument index, ... */\n")
	b.WriteString("    private static Map<String, Integer> ctxArg(Object... kv) {\n")
	b.WriteString("        Map<String, Integer> out = new LinkedHashMap<String, Integer>();\n")
	b.WriteString("        for (int i = 0; i < kv.length; i += 2) {\n")
	b.WriteString("            out.put((String) kv[i], (Integer) kv[i + 1]);\n        }\n")
	b.WriteString("        return Collections.unmodifiableMap(out);\n    }\n}\n")
	return b.Bytes()
}

// jstr renders s as a Java string literal (UTF-16 escapes outside printable ASCII).
func jstr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString(`\"`)
		case r == '\\':
			b.WriteString(`\\`)
		case r == '\n':
			b.WriteString(`\n`)
		case r == '\r':
			b.WriteString(`\r`)
		case r == '\t':
			b.WriteString(`\t`)
		case r >= 0x20 && r < 0x7f:
			b.WriteRune(r)
		case r > 0xffff:
			r -= 0x10000
			fmt.Fprintf(&b, `\u%04x\u%04x`, 0xd800+(r>>10), 0xdc00+(r&0x3ff))
		default:
			fmt.Fprintf(&b, `\u%04x`, r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func jlist(s []string) string {
	parts := make([]string, len(s))
	for i, v := range s {
		parts[i] = jstr(v)
	}
	return "list(" + strings.Join(parts, ", ") + ")"
}

func jctx(m map[string]int) string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, 2*len(keys))
	for _, k := range keys {
		parts = append(parts, jstr(k), strconv.Itoa(m[k]))
	}
	return "ctxArg(" + strings.Join(parts, ", ") + ")"
}
